import { jsx as _jsx } from "@opentui/solid/jsx-runtime";
/** @jsxImportSource @opentui/solid */
import { Plugin } from "@opencode/plugin/tui";
import { createSignal } from "solid-js";
import { registerCommands } from "./commands";
import { PLUGIN_VERSION } from "./_version";
import { getLogFilePath, logger } from "./logger";
import { detectLang } from "./i18n";
import { DEFAULT_DOCK_PLUGIN_OPTIONS, parseDockPluginOptions, } from "./plugin-options";
import { DOCK_TAB_ORDER } from "./dock-tab";
import { clampMaxEntries } from "./session-list";
import { clampDataDays } from "./data-range";
import { DockTabs } from "./ui/dock-tabs";
import { createHost, panelTheme } from "./host";
// ===================================================================
// 插件入口
// ===================================================================
/**
 * 插件标识。
 *
 * 这个字符串会被宿主直接拼进存储路径（`<数据目录>/<id>/tui/<key>.json`），
 * 因此必须满足宿主的存储段规则 `^[a-zA-Z0-9][a-zA-Z0-9._-]*$`，且不能是
 * `.` 或 `..`。带 scope 的包名（`@haisto/opencode-dock`）含 `@`
 * 与 `/`，会在第一次 `storage.store` 时被宿主拒绝并导致插件启动失败，
 * 所以这里用点号分隔的句柄，而不是包名。句柄沿用旧值，确保产品改名后
 * 宿主仍命中原来的存储目录，不丢失用户设置与历史条目。
 */
const PLUGIN_ID = "haisto.opencode-subagent-control";
/**
 * 读取某个分页的数据窗口天数。
 * 分页级配置优先，其次全局配置，最后回退产品默认值。
 */
function dataDaysFor(options, tab) {
    return clampDataDays(options.tabs?.[tab]?.dataDays ??
        options.dataDays ??
        DEFAULT_DOCK_PLUGIN_OPTIONS.dataDays);
}
/**
 * 从 options 建立五个界面信号。
 *
 * 配置只从插件 options 读取，不再依赖命令写入的持久化设置；
 * 分页级配置优先于全局配置，未配置时回退到产品默认值。
 */
function createSignals(options) {
    const [lang, setLang] = createSignal(options.lang ?? detectLang());
    const maxEntriesFor = (tab) => clampMaxEntries(options.tabs?.[tab]?.maxEntries ??
        options.maxEntries ??
        DEFAULT_DOCK_PLUGIN_OPTIONS.maxEntries);
    const [maxEntries, setMaxEntries] = createSignal(maxEntriesFor("subagents"));
    const [sessionMaxEntries, setSessionMaxEntries] = createSignal(maxEntriesFor("sessions"));
    const [projectMaxEntries, setProjectMaxEntries] = createSignal(maxEntriesFor("projects"));
    const [timelineMaxEntries, setTimelineMaxEntries] = createSignal(maxEntriesFor("timeline"));
    const [sortOrder, setSortOrder] = createSignal(options.tabs?.subagents?.sortOrder ??
        options.sortOrder ??
        DEFAULT_DOCK_PLUGIN_OPTIONS.sortOrder);
    const [scrollMode, setScrollMode] = createSignal(options.tabs?.subagents?.scrollMode ??
        options.scrollMode ??
        DEFAULT_DOCK_PLUGIN_OPTIONS.scrollMode);
    return {
        lang,
        setLang,
        maxEntries,
        setMaxEntries,
        sessionMaxEntries,
        setSessionMaxEntries,
        projectMaxEntries,
        setProjectMaxEntries,
        timelineMaxEntries,
        setTimelineMaxEntries,
        sortOrder,
        setSortOrder,
        scrollMode,
        setScrollMode,
        sessionId: "",
    };
}
/**
 * v2 插件的 setup 实现。
 *
 * 与 v1 的差别：插槽改为按点号路径声明（`sidebar.content`），命令改由 keymap
 * 图层注册，二者都返回注销函数，由 setup 返回的 cleanup 统一释放——宿主热重载
 * 时若不清，命令与插槽会一代代叠上去。
 */
function setup(context) {
    const options = parseDockPluginOptions(context.options);
    if (options.enabled === false) {
        logger.info("[plugin] 已被 options 禁用");
        return () => { };
    }
    const enabledTabs = DOCK_TAB_ORDER.filter((value) => options.tabs?.[value]?.enabled !== false);
    if (enabledTabs.length === 0) {
        logger.info("[plugin] 四个分页都被 options 禁用");
        return () => { };
    }
    logger.info("[plugin] 启动", { version: PLUGIN_VERSION, logFile: getLogFilePath() });
    const host = createHost(context);
    const signals = createSignals(options);
    /**
     * Dock 唯一的内容插槽。
     *
     * 两个面板不再各占一个插槽，而是由 DockTabs 在同一插槽内切换：
     * 宿主只挂载一个 sidebar.content，未激活面板的定时器与订阅随卸载释放。
     * 用 prepend 而非 append，原因与旧实现一致——避免掉到整个 Dock 最底部。
     */
    const disposeSlot = context.ui.slot({
        prepend: "sidebar.content",
        render: (input) => {
            /**
             * 渲染期副作用：命令侧只能拿到最近一次可见会话，无法拿到实时值。
             * 两个面板共用这个会话 ID，因此只在插槽入口写一次。
             */
            signals.sessionId = input.sessionID;
            return (_jsx(DockTabs, { theme: panelTheme(context.theme), api: host, lang: signals.lang, maxEntries: signals.maxEntries, sessionMaxEntries: signals.sessionMaxEntries, projectMaxEntries: signals.projectMaxEntries, timelineMaxEntries: signals.timelineMaxEntries, projectDataDays: dataDaysFor(options, "projects"), sessionDataDays: dataDaysFor(options, "sessions"), timelineDataDays: dataDaysFor(options, "timeline"), subagentDataDays: dataDaysFor(options, "subagents"), sortOrder: signals.sortOrder, scrollMode: signals.scrollMode, sessionId: input.sessionID, enabledTabs: enabledTabs }));
        },
    });
    registerCommands(context, host, signals);
    return () => {
        disposeSlot();
    };
}
/**
 * 插件模块导出对象。
 * 宿主的 v2 加载器只认 `{ id, setup }`，多一个字段少一个字段都会直接拒绝加载。
 */
export default Plugin.define({
    id: PLUGIN_ID,
    setup,
});
